import pandas as pd
import requests
import time
import random as _random
from datetime import datetime, timezone, timedelta

now = datetime.now(timezone.utc)
now_epoch = int(now.timestamp())

BASE = 'https://api.massive.com'

API_KEY = (
    (CREDENTIALS.get('MASSIVE_API_KEY') or '').strip()
    or (CREDENTIALS.get('POLYGON_API_KEY') or '').strip()
)

WATCHLIST = [
    'SPY', 'QQQ', 'IWM', 'DIA',
    'XLE', 'XLF', 'XLK', 'XLV', 'XLI', 'XLU',
    'AAPL', 'MSFT', 'NVDA', 'GOOGL', 'META', 'AMZN',
    'TSLA', 'AMD', 'NFLX', 'AVGO', 'COIN',
    'ORCL', 'CRM', 'ADBE', 'PLTR',
    'VXX', 'UVXY', 'SVXY', 'TQQQ', 'SQQQ',
    'MSTR', 'SMCI', 'RIVN', 'LCID', 'NIO', 'BABA', 'ARKK', 'GME', 'AMC', 'BB',
]

LOOKAHEAD_DAYS = 90

OUTPUT_COLUMNS = [
    'ticker', 'ex_dividend_date', 'days_to_ex_div',
    'cash_amount', 'frequency', 'pay_date',
    'declaration_date', 'record_date',
    'dividend_type', '_epoch',
]


def _emit_info_row(detail):
    return pd.DataFrame([{
        'ticker': 'INFO', 'ex_dividend_date': '', 'days_to_ex_div': None,
        'cash_amount': None, 'frequency': '', 'pay_date': '',
        'declaration_date': '', 'record_date': '', 'dividend_type': '',
        'error_detail': detail[:1500],
        '_epoch': now_epoch,
    }], columns=OUTPUT_COLUMNS + ['error_detail'])


if not API_KEY:
    df = _emit_info_row(
        'MASSIVE_API_KEY (or POLYGON_API_KEY) not set. Required for the dividends endpoint.'
    )
    GENERATE_RESULTS(df)
else:
    today_iso = now.date().isoformat()
    cutoff_iso = (now + timedelta(days=LOOKAHEAD_DAYS)).date().isoformat()

    rows = []
    errors = []
    auth_failed = False

    def _massive_get(url, params=None):
        params = dict(params or {})
        params['apiKey'] = API_KEY
        last_exc = None
        for attempt in range(2):
            try:
                r = requests.get(url, params=params, timeout=15)
                if r.status_code in (401, 403):
                    raise RuntimeError(
                        f'Massive returned {r.status_code} - bad key.'
                    )
                if r.status_code == 429:
                    time.sleep(3.0 + _random.random() * 2.0)
                    continue
                r.raise_for_status()
                return r.json() or {}
            except requests.exceptions.RequestException as exc:
                last_exc = exc
                if attempt == 0:
                    time.sleep(2.0)
                    continue
                raise
        if last_exc:
            raise last_exc
        return {}

    def _safe_float(v):
        if v is None:
            return None
        try:
            f = float(v)
        except Exception:
            return None
        if f != f:
            return None
        return f

    for ticker in WATCHLIST:
        if auth_failed:
            break
        time.sleep(0.3 + _random.random() * 0.2)

        try:
            url = f'{BASE}/v3/reference/dividends'
            params = {
                'ticker': ticker,
                'ex_dividend_date.gte': today_iso,
                'ex_dividend_date.lte': cutoff_iso,
                'order': 'asc',
                'sort': 'ex_dividend_date',
                'limit': 50,
            }
            payload = _massive_get(url, params)
        except RuntimeError as exc:
            errors.append(f'{ticker}:dividends:{exc}')
            auth_failed = True
            break
        except Exception as exc:
            errors.append(f'{ticker}:dividends:{exc}')
            continue

        results = payload.get('results') or []
        if not isinstance(results, list):
            continue
        for entry in results:
            ex_date = str(entry.get('ex_dividend_date', '') or '')
            if not ex_date:
                continue
            try:
                ex_dt = datetime.strptime(ex_date, '%Y-%m-%d').replace(tzinfo=timezone.utc)
            except Exception:
                continue
            days_to = (ex_dt - now).total_seconds() / 86400.0
            cash = _safe_float(entry.get('cash_amount'))
            rows.append({
                'ticker': ticker,
                'ex_dividend_date': ex_date,
                'days_to_ex_div': round(days_to, 1),
                'cash_amount': round(cash, 4) if cash is not None else None,
                'frequency': str(entry.get('frequency', '')),
                'pay_date': str(entry.get('pay_date', '')),
                'declaration_date': str(entry.get('declaration_date', '')),
                'record_date': str(entry.get('record_date', '')),
                'dividend_type': str(entry.get('dividend_type', '')),
                '_epoch': now_epoch,
            })

    if rows:
        df = pd.DataFrame(rows, columns=OUTPUT_COLUMNS)
        df = df.sort_values(['days_to_ex_div', 'ticker']).reset_index(drop=True)
    else:
        detail = '; '.join(errors) if errors else (
            f'No upcoming dividends in the next {LOOKAHEAD_DAYS} days for the 40-ticker watchlist. '
            f'This is uncommon for an 8-quarter-typical sector mix; verify the watchlist contains '
            f'dividend-paying names if 0 rows persists across multiple runs.'
        )
        if auth_failed:
            detail = 'MASSIVE_API_KEY rejected. ' + detail
        df = _emit_info_row(detail)
    GENERATE_RESULTS(df)
